def _mix(mine, orig):
    w = [it for it in orig if it['lv'] == '서술']; assert len(w) == 1 and orig[4] is w[0]
    new = mine[:4] + [orig[4]] + mine[4:]
    assert [it['lv'] for it in new] == [it['lv'] for it in orig], [it['lv'] for it in new]
    return new
